h1.site-title {
    font-size: 40px;
    font-style: italic;
	  color: #000;
		font-family: Revalia;
    text-shadow: 0 0 8px #FFF;
}

.site-description{
    font-size: 18px;
    font-style: italic;
    color: #000;
 	  font-family: Quattrocento !important; 
    text-shadow: 0 0 6px #FFF;
}

.blaskan-main-menu:hover{
  color: blue;
}

.blog a:hover {
    color: purple;

}

.site-content p{font-family:Copse;}

/*background color #e4faf2*/
body {
 background: #e3e3e3 ;
}



/*footer*/

footer {
  display: flex;
  justify-content: center;
	font-size: 12px !important;
	color:#8B008B;
}

/*color anchor*/

a {
  color: #0031FF;
}

a:link{
 color: #0031FF;
}

div.entry-meta{
	color:#0031FF;
}

aside{
	color:#0031FF;
}

span.byline{
	color:#0031FF;
}

a:hover {
  color:blueviolet ;
}

a:visited {
  color: #B800FF;
}

a.more-link, button {
background-color: #04AA6D;
  border: 1px;
	font-family: helvetica;
	text-transform: uppercase;
	font-weight: bold;
  color: #00e7ff !important;
  padding: 12px;
  text-align: center;
  display: inline-block;
  margin: 2px 2px;
	border-radius: 2px;
}



}

/*Centers widget titles and changes font size*/

.widget-title  {
    font-size: 16px;
    font-weight: 300;
    text-align: center;
}

.widget {
    font-family:cambria;
	  align-content;
	  font-size: 14px;
    font-weight: 200;
    text-align: left;
}

.widget ul {
    list-style: none;
    margin: 0;
}

.widget.posts{
	font-family:cambria;
}

.widget.archives{
	font-family:cambria;
}
/*page number*/

 .page-numbers {text-align: center;}

.copyright-info {visibility: visible; text-align: right;}

.entry-content a:not(.more-link):not(.wp-block-button__link):hover {
    color: blueviolet;
}


/*tagcloud*/
.tagcloud, .widget_tag_cloud, .wp_widget_tag_cloud {
    line-height: 1.5;
}

.tagcloud ul li {
    float: left;
    border-top: 0;
    border-bottom: 0;
    padding: 0;
    margin: 4px 4px 0 0;
}

.tagcloud a { font-family:cambria; opacity: 0.80; color: #FFF; display: inline-block; margin: 0 5px 5px 0; padding: 0 6px; line-height: 30px; border-radius: 5px; } .tagcloud a:nth-child(9n){background-color: #4A4A4A;} .tagcloud a:nth-child(9n+1){background-color: #428BCA;} .tagcloud a:nth-child(9n+2){background-color: #5CB85C;} .tagcloud a:nth-child(9n+3){background-color: #D9534F;} .tagcloud a:nth-child(9n+4){background-color: #567E95;} .tagcloud a:nth-child(9n+5){background-color: #B433FF;} .tagcloud a:nth-child(9n+6){background-color: #00ABA9;} .tagcloud a:nth-child(9n+7){background-color: #B37333;} .tagcloud a:nth-child(9n+8){background-color: #FF6600;} 

